INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00j5pct1twe385ly', NULL, 'How fast do orders start?', 'Most services start within 0-30 minutes. Large orders are drip-fed automatically to keep accounts safe.', 'Orders', 0);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00j6pct1oxxkb8zh', NULL, 'What payment methods do you accept?', 'Credit/debit cards, PayPal, Crypto (Binance Pay, USDT) and bank transfer.', 'Payments', 1);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00j7pct1jzsslfc9', NULL, 'Do you offer refunds?', 'If we cannot deliver your order, it is refunded to your balance automatically. Partial deliveries are refunded pro-rata.', 'Payments', 2);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00j8pct12ieltx2l', NULL, 'Is there an API?', 'Yes — a standard SMM API v2 endpoint is included with every account, plus API docs in your portal.', 'API', 3);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00j9pct11zl0ubmz', NULL, 'Can I resell with my own brand?', 'Absolutely. Buy a reseller plan and you get your own branded panel on a free subdomain or your custom domain.', 'Reseller', 4);
INSERT INTO "Faq" ("id", "platformId", "question", "answer", "category", "sortOrder") VALUES ('cmtxjxpqr00japct184hpklih', NULL, 'Do services come with refill?', 'Most services include a 30-day refill guarantee — check the refill badge on each service.', 'Orders', 5);
